raw:
{
  "spells": [
    {
      "id": "spell_space_13",
      "theory": "双锚迁行将魔力同时注入两枚已登记的锚点，使它们短暂共鸣，在共鸣路径上打开一道仅供一人通过的狭缝。锚点通常由树脂封存的符文构成，共鸣要求两处符文纹路完全对应。迁行过程不探测未登记地点，因此不会意外落入未知洞穴或他人宅邸。",
      "casting": "双手各持一枚锚点石，以拇指按压符文并同步注入等量魔力，待两石微热时向前迈出一步。",
      "failure": "若两枚锚点石受热不均，狭缝会在中途收缩，迁行者被弹回出发侧并感到短暂眩晕，衣物可能被空间褶皱割出裂口。",
      "counters": [
        "在锚点符文上覆盖一层薄铅，可阻断共鸣所需的魔力通路。",
        "将受术者与锚点石分开超过十步，迁行便无法启动。"
      ],
      "socialConsequences": "河谷乡约要求迁行前向见证人说明出发与抵达的锚点，防止有人借传送逃避债务或私奔。城市公会凭许可记录锚点位置，盗用他人锚点会被追究。港口则关注货损责任，若迁行货物在途中受空间褶皱损伤，港务会要求操作者赔偿并暂停其锚点使用权。",
      "law": {
        "river": "permit",
        "city": "permit",
        "port": "permit"
      },
      "proficiencyEffects": [
        "初学时两枚锚点石常因受热不均而弹回，需多次校准。",
        "熟练后能稳定维持狭缝，使一人携带轻便行李通过。",
        "精准控制可减少空间褶皱，降低衣物与皮肤擦伤风险。",
        "高熟练度下迁行落点更贴近预定位置，误差不超过一步。"
      ]
    },
    {
      "id": "spell_space_14",
      "theory": "界隙缝合以魔力为针，将树脂熔成细丝，沿空间异常的边缘往复穿梭，使裂口两侧的介质重新贴合。缝合只针对小型异常，如因魔力泄漏而出现的指宽裂隙。神性裂隙因蕴含远超施术者容量的力量，无法被此术封闭。",
      "casting": "右手食指与中指并拢作针状，蘸取熔化的树脂，沿裂隙边缘快速来回划动，同时左手稳住锚点石。",
      "failure": "树脂冷却过快会在裂隙表面形成脆壳，壳下异常仍在，数小时后可能崩裂并发出尖锐嗡鸣，惊动附近的人。",
      "counters": [
        "向裂隙撒布细沙可暂时标记边缘，使缝合线偏离中心而失效。",
        "在缝合完成前用强风扰动树脂丝，能使其断裂并散落。"
      ],
      "socialConsequences": "河谷村民会请缝合者修补因融雪或树根挤压出现的空间细缝，避免牲畜失足。城市公会记录每次缝合的位置与时间，若同一处反复开裂，会要求检查地下魔力管线。港口则担心缝合不牢导致货物掉入裂隙，港务规定缝合后须静置一昼夜方可通行，违者承担货损。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "初学时常因树脂冷却过快而留下脆壳，需反复练习。",
        "熟练者能拉出均匀树脂丝，使缝合边缘平整贴合。",
        "精准控制可减少对周围介质的扰动，避免误缝他物。",
        "高熟练度下缝合处几乎不留痕迹，仍无法封闭神性裂隙。"
      ]
    }
  ]
}
